import numpy as np

def entropy(p):
    p = np.asarray(p, dtype=float)
    terms = np.where(p > 0, p * np.log2(p, where=p > 0), 0.0)
    return -np.sum(terms)

print(entropy(np.array([0.5, 0.5, 0.0])))   # 1.0 -- the zero-probability outcome contributes nothing, correctly

