import numpy as np

def entropy(p):
    p = p[p > 0]
    return -np.sum(p * np.log2(p))

def kl_divergence(p, q):
    mask = p > 0
    return np.sum(p[mask] * np.log2(p[mask] / q[mask]))

def cross_entropy(p, q):
    mask = p > 0
    return -np.sum(p[mask] * np.log2(q[mask]))

rng = np.random.default_rng(seed=11)
for trial in range(3):
    p = rng.dirichlet(alpha=[1, 1, 1, 1])
    q = rng.dirichlet(alpha=[1, 1, 1, 1])
    lhs = entropy(p) + kl_divergence(p, q)
    rhs = cross_entropy(p, q)
    print(f"trial {trial}: H(P)+KL(P||Q)={lhs:.6f}  H(P,Q)={rhs:.6f}  equal? {np.isclose(lhs, rhs)}")
